def is_prime(n: int) -> bool:
    """
    Returns True if integer n is a prime number, False otherwise.

    >>> is_prime(7)
    True
    >>> is_prime(4)
    False
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def extended_gcd(a: int, b: int) -> tuple[int, int, int]:
    """
    Computes integers (g, x, y) such that a*x + b*y = g = gcd(a, b).

    >>> extended_gcd(30, 20)
    (10, 1, -1)
    """
    if b == 0:
        return (a, 1, 0)
    g, x1, y1 = extended_gcd(b, a % b)
    x = y1
    y = x1 - (a // b) * y1
    return (g, x, y)

def dot_product_vectors(v1: list[float], v2: list[float]) -> float:
    """
    Calculates the dot product of two vectors of equal length.

    >>> dot_product_vectors([1.0, 2.0], [3.0, 4.0])
    11.0
    """
    if len(v1) != len(v2):
        raise ValueError('Vectors must have equal length')
    return sum(a * b for a, b in zip(v1, v2))

def is_deficient_number(n: int) -> bool:
    """
    Checks if sum of proper divisors of positive integer n is strictly less than n.

    >>> is_deficient_number(15)
    True
    >>> is_deficient_number(12)
    False
    """
    if n <= 0:
        return False
    if n == 1:
        return True
    total = 1
    for d in range(2, int(n**0.5) + 1):
        if n % d == 0:
            total += d
            if d != n // d:
                total += n // d
    return total < n
